# Stage 0: build the source port (README_STAGE0.md): build\acnb.exe (i686 while game structs keep the PS2 layout, llvm-mingw). No emulation.
#   decompiled game code: ..\port\src, ..\port\lib (+ ..\port\hooks), compiled with -DACNB_SOURCEPORT and the
#                         source-port prelude ..\port\gen\sp\<rel>.h force-included
#   main\*.cpp            entry point + platform side (host_rq.cpp: rq_host.h + the Rq instance)
#   ..\port\render       render module (null backend until phase 3), -DRQ_HOST_ADDR
#   build\gen\stub_*.cpp  generated by scripts\sp_missing.py for everything not decompiled yet; the same run writes
# build\ (Versus progress + missing functions by module)
param([switch]$Release, [switch]$Clean)
$ErrorActionPreference = 'Stop'
$root = $PSScriptRoot
$top = Split-Path $root
$port = Join-Path $top 'port'
$bin = Join-Path $top 'tools\llvm-mingw-20260922-ucrt-x86_64\bin'
$cxx = Join-Path $bin 'i686-w64-mingw32-clang++.exe'
$out = Join-Path $root 'build'
$objdir = Join-Path $out ($(if ($Release) { 'obj-rel' } else { 'obj-dbg' }))
$gameDir = Join-Path $objdir 'game'   # decompiled code only: sp_missing.py reads its symbol tables
$hostDir = Join-Path $objdir 'host'
$gen = Join-Path $out 'gen'
if ($Clean -and (Test-Path $objdir)) { Remove-Item -Recurse -Force $objdir }
New-Item -ItemType Directory -Force $out, $gameDir, $hostDir, $gen | Out-Null

python (Join-Path $top 'scripts\gen_sp.py')   # the source-port preludes port\gen\sp + port\gen\sp_natives.txt
if ($LASTEXITCODE) { exit 1 }

$common = @(if ($Release) { '-O2', '-g' } else { '-O1', '-g' })
$common += @('-m32', '-mno-ms-bitfields', '-fno-auto-import', '-DACNB_SOURCEPORT', '-std=c++20', '-fno-exceptions',
             '-fno-rtti', '-Wall', '-Wno-unused-function', '-Wno-address-of-packed-member', '-Wno-unused-but-set-global',
             '-Wno-c99-designator', '-Wno-c11-extensions', '-Wno-main', '-Wno-undefined-internal',
             "-I$port\include", "-I$port\gen", "-I$root\main")

function NeedsBuild($src, $obj) {
    if (-not (Test-Path $obj)) { return $true }
    $t = (Get-Item $obj).LastWriteTimeUtc
    $d = [IO.Path]::ChangeExtension($obj, '.d')
    $deps = @($src)
    if (Test-Path $d) {
        $txt = (Get-Content $d -Raw) -replace '\\\r?\n', ' '
        $deps = ($txt.Substring($txt.IndexOf(': ') + 2) -split '(?<!\\)\s+') | Where-Object { $_ } | ForEach-Object { $_ -replace '\\ ', ' ' }
    }
    foreach ($p in $deps) { if (-not (Test-Path $p) -or (Get-Item $p).LastWriteTimeUtc -gt $t) { return $true } }
    return $false
}

# compiles (source, object, extra args) units in parallel; returns the objects
function Compile($units) {
    $procs = @()
    foreach ($u in $units) {
        $src, $obj, $extra = $u
        if (-not (NeedsBuild $src $obj)) { continue }
        $d = [IO.Path]::ChangeExtension($obj, '.d')
        # Start-Process joins the list into one command line: quote arguments with spaces (repo path)
        $q = @($common + $extra | ForEach-Object { if ($_ -match ' ') { "`"$_`"" } else { $_ } })
        $cargs = $q + @('-MMD', '-MF', "`"$d`"") + @('-c', "`"$src`"", '-o', "`"$obj`"")
        $p = Start-Process -FilePath $cxx -ArgumentList $cargs -NoNewWindow -PassThru
        $null = $p.Handle   # keeps ExitCode available after exit
        $procs += , @($p, $src)
    }
    $fail = 0
    foreach ($p in $procs) { $p[0].WaitForExit(); if ($p[0].ExitCode) { Write-Host "FAILED: $($p[1])"; $fail = 1 } }
    if ($fail) { exit 1 }
    Write-Host "compiled $($procs.Count) of $($units.Count) units"
    return $units | ForEach-Object { $_[1] }
}

# 1. decompiled game code
$game = @()
foreach ($t in 'src', 'lib') {
    foreach ($f in Get-ChildItem "$port\$t" -Recurse -Include *.cpp | Where-Object { $_.FullName -notlike "$port\src\iop\*" }) {
        $rel = $f.FullName.Substring($port.Length + 1, $f.FullName.Length - $port.Length - 1 - $f.Extension.Length)
        $game += , @($f.FullName, "$gameDir\$($rel -replace '\\', '_').o", @('-include', "$port\gen\sp\$rel.h"))
    }
}
foreach ($f in Get-ChildItem "$port\hooks\*.cpp") { $game += , @($f.FullName, "$gameDir\hk_$($f.BaseName).o", @()) }
$live = $game | ForEach-Object { Split-Path -Leaf $_[1] }
Get-ChildItem "$gameDir\*.o" | Where-Object Name -notin $live | Remove-Item   # objects of deleted sources
$gameObjs = Compile $game

# 2. stubs for whatever is still missing + report (input: the game objects only)
python (Join-Path $top 'scripts\sp_missing.py') (Join-Path $bin 'llvm-nm.exe') $gameDir $gen (Join-Path $out 'missing.md')
if ($LASTEXITCODE) { exit 1 }

# 3. generated stubs + host side
Get-ChildItem "$hostDir\stub_*.o" | Remove-Item   # the stub set changes with every decompiled function
$rest = @()
foreach ($f in Get-ChildItem "$gen\stub_*.cpp") { $rest += , @($f.FullName, "$hostDir\$($f.BaseName).o", @()) }
foreach ($f in Get-ChildItem "$root\main\*.cpp") { $rest += , @($f.FullName, "$hostDir\main_$($f.BaseName).o", @()) }
# render module (port/render, one copy in both builds; design rule 1): no game prelude, host-pointer DMA addresses
foreach ($f in Get-ChildItem "$port\render\*.cpp") { $rest += , @($f.FullName, "$hostDir\rq_$($f.BaseName).o", @('-DRQ_HOST_ADDR')) }
# platform module (port/platform, phase 3: disc / ps2_file / trace / disc_id / elfdata / ovlreg; one copy in both builds)
# padin (live pad input) includes the SDL3 headers; SDL3 itself is loaded at run time (SDL3.dll copied beside acnb.exe)
$sdl = Join-Path $top 'tools\SDL3-3.4.18\i686-w64-mingw32'
foreach ($f in Get-ChildItem "$port\platform\*.cpp") { $rest += , @($f.FullName, "$hostDir\pf_$($f.BaseName).o", @("-I$sdl\include")) }
# window + presenter (port/platform/video, boot slice B1): SDL3 window / GL 4.5 context for the render module; source
# port only (the hybrid presents through runtime/video.c)
foreach ($f in Get-ChildItem "$port\platform\video\*.cpp") { $rest += , @($f.FullName, "$hostDir\vid_$($f.BaseName).o", @("-I$sdl\include")) }
# audio device (port/platform/audio, phase 3 step 5 N9): mixer tap -> SDL3 audio stream; source port only
foreach ($f in Get-ChildItem "$port\platform\audio\*.cpp") { $rest += , @($f.FullName, "$hostDir\aud_$($f.BaseName).o", @("-I$sdl\include")) }
# native EE kernel (port/platform/kern, boot slice B2): fibers, threads, semas, DIntr / EIntr; source port only (the
# hybrid keeps runtime/kernel.c)
foreach ($f in Get-ChildItem "$port\platform\kern\*.cpp") { $rest += , @($f.FullName, "$hostDir\kern_$($f.BaseName).o", @()) }
# native sound (port/platform/snd, phase 3 step 5 NI2): mixer + its --spu-selftest, one copy in both builds
foreach ($f in Get-ChildItem "$port\platform\snd\*.cpp") { $rest += , @($f.FullName, "$hostDir\snd_$($f.BaseName).o", @()) }
# sandbox (port/platform/sandbox: the v3 replay event player + its expression evaluator); backend main\host_sbx.cpp
foreach ($f in Get-ChildItem "$port\platform\sandbox\*.cpp") { $rest += , @($f.FullName, "$hostDir\sbx_$($f.BaseName).o", @()) }
# names (port/platform/names) + logical state hash, = the hybrid
foreach ($f in Get-ChildItem "$port\platform\names\*.cpp") { $rest += , @($f.FullName, "$hostDir\nm_$($f.BaseName).o", @()) }
foreach ($f in Get-ChildItem "$port\platform\statehash\*.cpp") { $rest += , @($f.FullName, "$hostDir\st_$($f.BaseName).o", @()) }
# native libsd (port/platform/snd/iop, phase 3 step 5 NI3): sd API + its --sd-selftest
foreach ($f in Get-ChildItem "$port\platform\snd\iop\*.cpp") { $rest += , @($f.FullName, "$hostDir\sdi_$($f.BaseName).o", @()) }
# native FromSoftware IOP modules (port/src/iop, NI5b): IOP code, not game code (no prelude, not in the stub scan)
foreach ($f in Get-ChildItem "$port\src\iop\*.cpp") { $rest += , @($f.FullName, "$hostDir\iop_$($f.BaseName).o", @()) }
$restObjs = Compile $rest

# link arguments through a response file (forward slashes, quoted): paths with spaces break on the direct command line
$rsp = Join-Path $out 'link.rsp'
@($common + '-municode' + $gameObjs + $restObjs + '-o' + "$out\acnb.exe" + "-Wl,-Map=$out\acnb.map") |
    ForEach-Object { '"' + ($_ -replace '\\', '/') + '"' } | Set-Content -Encoding ascii $rsp
& $cxx "@$rsp"
if ($LASTEXITCODE) { exit 1 }
# sandbox name table from this link's map (module base + RVA; sentinels refuse a table from an older link)
python (Join-Path $top 'scripts\sbx_names.py') sourceport $out "$out\acnb.map"
if ($LASTEXITCODE) { exit 1 }
Copy-Item "$sdl\bin\SDL3.dll" $out -Force   # padin (gamepads) + video (window / GL context), loaded at run time
Copy-Item "$sdl\..\LICENSE.txt" "$out\SDL3-LICENSE.txt" -Force   # zlib licence: ships with the DLL
Write-Host "built $out\acnb.exe"
